import{_ as o,r as s,o as p,c as l,e as a,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Контроллер связей - October CMS - 3.x","titleTemplate":false,"description":"Управляет вложенными данными форм с использованием связанных записей.","frontmatter":{"subtitle":"Управляет вложенными данными форм с использованием связанных записей."},"headers":[{"level":2,"title":"Настройка поведения связей","slug":"настроика-поведения-связеи","link":"#настроика-поведения-связеи","children":[{"level":3,"title":"Пользовательские сообщения","slug":"пользовательские-сообщения","link":"#пользовательские-сообщения","children":[]},{"level":3,"title":"Вложенные определения","slug":"вложенные-определения","link":"#вложенные-определения","children":[]}]},{"level":2,"title":"Типы связей","slug":"типы-связеи","link":"#типы-связеи","children":[{"level":3,"title":"Has Many","slug":"has-many","link":"#has-many","children":[]},{"level":3,"title":"Belongs to Many","slug":"belongs-to-many","link":"#belongs-to-many","children":[]},{"level":3,"title":"Belongs to Many (с данными сводной таблицы)","slug":"belongs-to-many-с-данными-своднои-таблицы","link":"#belongs-to-many-с-данными-своднои-таблицы","children":[]},{"level":3,"title":"Belongs To","slug":"belongs-to","link":"#belongs-to","children":[]},{"level":3,"title":"Has One","slug":"has-one","link":"#has-one","children":[]}]},{"level":2,"title":"Отображение менеджера связей","slug":"отображение-менеджера-связеи","link":"#отображение-менеджера-связеи","children":[]},{"level":2,"title":"Расширение поведения связей","slug":"расширение-поведения-связеи","link":"#расширение-поведения-связеи","children":[{"level":3,"title":"Расширение конфигурации связей","slug":"расширение-конфигурации-связеи","link":"#расширение-конфигурации-связеи","children":[]},{"level":3,"title":"Расширение виджета представления","slug":"расширение-виджета-представления","link":"#расширение-виджета-представления","children":[{"level":4,"title":"Как удалить столбец","slug":"как-удалить-столбец","link":"#как-удалить-столбец","children":[]}]},{"level":3,"title":"Расширение виджета управления","slug":"расширение-виджета-управления","link":"#расширение-виджета-управления","children":[]},{"level":3,"title":"Расширение виджета сводной таблицы","slug":"расширение-виджета-своднои-таблицы","link":"#расширение-виджета-своднои-таблицы","children":[]},{"level":3,"title":"Расширение виджетов фильтрации","slug":"расширение-виджетов-фильтрации","link":"#расширение-виджетов-фильтрации","children":[]},{"level":3,"title":"Расширение обновления результатов","slug":"расширение-обновления-результатов","link":"#расширение-обновления-результатов","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/extend/forms/relation-controller.md","filePath":"3.x/ru/extend/forms/relation-controller.md"}'),i={name:"3.x/ru/extend/forms/relation-controller.md"};function d(u,n,k,g,m,h){const t=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[a(t),n[0]||(n[0]=c("h1",null,"Контроллер связей",-1)),a(e),n[1]||(n[1]=r(`<p>Класс <code>Backend\\Behaviors\\RelationController</code> — это поведение контроллера, используемое для простого управления сложными <a href="./../database/model.html">связями моделей</a> на странице.</p><p>Поведение связей зависит от типов связей, указанных ниже. Для использования поведения связей вы должны добавить определение <code>Backend\\Behaviors\\RelationController</code> в поле <code>$implement</code> класса контроллера. Также должно быть определено свойство класса <code>$relationConfig</code>, значение которого должно ссылаться на YAML-файл, используемый для настройки свойств поведения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Projects<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Projects</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$formConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_form.yaml&#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">public</span> <span class="token variable">$relationConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_relation.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Очень часто контроллер связей используется вместе с <a href="./form-controller.html">контроллером форм</a>.</p></div><h2 id="настроика-поведения-связеи"><a href="#настроика-поведения-связеи" class="header-anchor">#</a> Настройка поведения связей</h2><p>Файл конфигурации, указанный в свойстве <code>$relationConfig</code>, определяется в формате YAML. Файл должен быть размещён в <a href="./../system/views.html">директории представлений контроллера</a>. Необходимая конфигурация зависит от типа связи между целевой моделью и связанной моделью.</p><p>Поле первого уровня в файле конфигурации связей определяет имя связи в целевой модели. Например.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Invoice</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Pay<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>InvoiceItem</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Модель <code>Invoice</code> со связью <code>items</code> должна определить поле первого уровня с тем же именем связи.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">items</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Invoice Line Item
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/pay/models/invoiceitem/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>delete
        <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token number">10</span>
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/pay/models/invoiceitem/fields.yaml
</code></pre></div><p>Следующие свойства используются для каждого определения имени связи.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>метка для связи в единственном числе, обязательно.</td></tr><tr><td><strong>view</strong></td><td>конфигурация, специфичная для контейнера представления, см. ниже.</td></tr><tr><td><strong>manage</strong></td><td>конфигурация, специфичная для всплывающего окна управления, см. ниже.</td></tr><tr><td><strong>pivot</strong></td><td>ссылка на файл определения полей формы, используется для связей с данными сводной таблицы.</td></tr><tr><td><strong>emptyMessage</strong></td><td>сообщение для отображения, когда связь пуста, необязательно.</td></tr><tr><td><strong>readOnly</strong></td><td>отключает возможность добавления, обновления, удаления или создания связей. По умолчанию: <code>false</code></td></tr><tr><td><strong>deferredBinding</strong></td><td><a href="./../database/relations.html">откладывает все действия привязки с использованием ключа сессии</a>, когда он доступен. По умолчанию: <code>false</code></td></tr><tr><td><strong>popupSize</strong></td><td>изменяет размер всплывающих окон управления, варианты: <code>giant</code>, <code>huge</code>, <code>large</code>, <code>small</code>, <code>tiny</code> или <code>adaptive</code>. По умолчанию: <code>huge</code></td></tr><tr><td><strong>valueFrom</strong></td><td>определяет пользовательский атрибут модели для использования в качестве исходного значения. По умолчанию берётся из имени определения.</td></tr></tbody></table></div><p>Эти значения конфигурации могут быть указаны для свойств <strong>view</strong> или <strong>manage</strong>, где применимо к типу рендеринга списка, формы или обоих.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><strong>form</strong></td><td>Форма</td><td>ссылка на файл определения полей формы, см. <a href="./../../element/form-fields.html">поля формы панели управления</a>.</td></tr><tr><td><strong>list</strong></td><td>Список</td><td>ссылка на файл определения столбцов списка, см. <a href="./../../element/list-columns.html">столбцы списка панели управления</a>.</td></tr><tr><td><strong>showFlash</strong></td><td>Оба</td><td>включает отображение flash-сообщений после успешного действия. По умолчанию: <code>true</code></td></tr><tr><td><strong>showSearch</strong></td><td>Список</td><td>отображает поле ввода для поиска записей. По умолчанию: <code>false</code></td></tr><tr><td><strong>showSorting</strong></td><td>Список</td><td>отображает ссылку сортировки на каждом столбце. По умолчанию: <code>true</code></td></tr><tr><td><strong>showSetup</strong></td><td>Список</td><td>отображает кнопку настройки для конфигурации столбцов списка и записей на странице. По умолчанию: <code>false</code></td></tr><tr><td><strong>defaultSort</strong></td><td>Список</td><td>устанавливает столбец и направление сортировки по умолчанию, когда пользовательские предпочтения не определены. Поддерживает строку или массив с ключами <code>column</code> и <code>direction</code>. Направление может быть <code>asc</code> для восходящего (по умолчанию) или <code>desc</code> для нисходящего порядка.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>Список</td><td>максимальное количество строк для отображения на каждой странице.</td></tr><tr><td><strong>noRecordsMessage</strong></td><td>Список</td><td>сообщение для отображения, когда записи не найдены, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>conditions</strong></td><td>Список</td><td>указывает сырое выражение where-запроса для применения к запросу модели списка.</td></tr><tr><td><strong>scope</strong></td><td>Список</td><td>указывает метод <a href="./../database/model.html">области запроса модели</a>, определённый в связанной модели формы, для применения к запросу списка всегда. Модель, к которой будет прикреплена эта связь (т.е. родительская модель), передаётся в этот метод области вторым параметром (<code>$query</code> — первый).</td></tr><tr><td><strong>searchMode</strong></td><td>Список</td><td>определяет стратегию поиска: содержать все слова, любое слово или точную фразу. Поддерживаемые варианты: <code>all</code>, <code>any</code>, <code>exact</code>. По умолчанию: <code>all</code>.</td></tr><tr><td><strong>searchScope</strong></td><td>Список</td><td>указывает метод <a href="./../database/model.html">области запроса модели</a>, определённый в связанной модели формы, для применения к поисковому запросу, первый аргумент будет содержать поисковый термин.</td></tr><tr><td><strong>filter</strong></td><td>Список</td><td>ссылка на файл определения областей фильтрации, см. <a href="./../lists/filters.html">фильтры списков панели управления</a>.</td></tr><tr><td><strong>customPageName</strong></td><td>Список</td><td>указывает пользовательское имя переменной для использования в URL страницы для пагинированных записей. Установите <code>false</code> для отключения сохранения номера страницы в URL.</td></tr></tbody></table></div><p>Эти значения конфигурации могут быть указаны только для свойства <strong>view</strong>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><strong>showCheckboxes</strong></td><td>Список</td><td>отображает флажки рядом с каждой записью.</td></tr><tr><td><strong>recordUrl</strong></td><td>Список</td><td>связывает каждую запись списка с другой страницей. Например: <strong>users/update/:id</strong>. Часть <code>:id</code> заменяется идентификатором записи.</td></tr><tr><td><strong>customViewPath</strong></td><td>Список</td><td>указывает пользовательский путь представления для переопределения частичных представлений, используемых списком.</td></tr><tr><td><strong>recordOnClick</strong></td><td>Список</td><td>пользовательский JavaScript-код для выполнения при клике на запись.</td></tr><tr><td><strong>toolbarPartial</strong></td><td>Оба</td><td>ссылка на файл частичного представления контроллера с кнопками панели инструментов. Например: <code>_relation_toolbar.php</code>. Это свойство переопределяет свойство <code>toolbarButtons</code>.</td></tr><tr><td><strong>toolbarButtons</strong></td><td>Оба</td><td>набор отображаемых кнопок. Может быть отформатирован как массив или строка, разделённая вертикальной чертой, или установлен в <code>false</code> для скрытия кнопок. Доступные варианты: <code>create</code>, <code>update</code>, <code>delete</code>, <code>add</code>, <code>remove</code>, <code>link</code> и <code>unlink</code>. Пример: \`add</td></tr><tr><td><strong>structure</strong></td><td>Список</td><td>параметры для включения <a href="./../lists/structures.html">сортировки записей</a> для списка.</td></tr></tbody></table></div><p>Эти значения конфигурации могут быть указаны только для свойства <strong>manage</strong>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>Оба</td><td>заголовок всплывающего окна, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>context</strong></td><td>Форма</td><td>контекст отображаемой формы. Может быть строкой или массивом с ключами: <code>create</code>, <code>update</code>.</td></tr></tbody></table></div><h3 id="пользовательские-сообщения"><a href="#пользовательские-сообщения" class="header-anchor">#</a> Пользовательские сообщения</h3><p>Укажите свойство <code>customMessages</code> для переопределения сообщений по умолчанию, используемых контроллером связей. Значения могут быть обычным текстом или ссылаться на <a href="./../system/localization.html">строку локализации</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> Make Thing
    <span class="token key atrule">buttonDelete</span><span class="token punctuation">:</span> Destroy Thing
</code></pre></div><p>Вы также можете изменять сообщения в контексте отображаемого связанного поля. Следующий пример переопределит сообщение <code>createButton</code> только для связи <code>items</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">items</span><span class="token punctuation">:</span>
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> New Item<span class="token tag">!</span>
</code></pre></div><p>Следующие сообщения доступны для переопределения.</p><details class="custom-block details"><summary>Просмотр списка доступных сообщений</summary><div class="table"><table tabindex="0"><thead><tr><th>Сообщение</th><th>Сообщение по умолчанию</th></tr></thead><tbody><tr><td><strong>buttonCreate</strong></td><td>Create :name</td></tr><tr><td><strong>buttonCreateForm</strong></td><td>Create</td></tr><tr><td><strong>buttonCancelForm</strong></td><td>Cancel</td></tr><tr><td><strong>buttonCloseForm</strong></td><td>Close</td></tr><tr><td><strong>buttonUpdate</strong></td><td>Update :name</td></tr><tr><td><strong>buttonUpdateForm</strong></td><td>Update</td></tr><tr><td><strong>buttonAdd</strong></td><td>Add :name</td></tr><tr><td><strong>buttonAddMany</strong></td><td>Add Selected</td></tr><tr><td><strong>buttonAddForm</strong></td><td>Add</td></tr><tr><td><strong>buttonLink</strong></td><td>Link :name</td></tr><tr><td><strong>buttonDelete</strong></td><td>Delete</td></tr><tr><td><strong>buttonDeleteMany</strong></td><td>Delete Selected</td></tr><tr><td><strong>buttonRemove</strong></td><td>Remove</td></tr><tr><td><strong>buttonRemoveMany</strong></td><td>Remove Selected</td></tr><tr><td><strong>buttonUnlink</strong></td><td>Unlink</td></tr><tr><td><strong>buttonUnlinkMany</strong></td><td>Unlink Selected</td></tr><tr><td><strong>confirmDelete</strong></td><td>Are you sure?</td></tr><tr><td><strong>confirmUnlink</strong></td><td>Are you sure?</td></tr><tr><td><strong>titlePreviewForm</strong></td><td>Preview :name</td></tr><tr><td><strong>titleCreateForm</strong></td><td>Create :name</td></tr><tr><td><strong>titleUpdateForm</strong></td><td>Update :name</td></tr><tr><td><strong>titleLinkForm</strong></td><td>Link a New :name</td></tr><tr><td><strong>titleAddForm</strong></td><td>Add a New :name</td></tr><tr><td><strong>titlePivotForm</strong></td><td>Related :name Data</td></tr><tr><td><strong>flashCreate</strong></td><td>:name Created</td></tr><tr><td><strong>flashUpdate</strong></td><td>:name Updated</td></tr><tr><td><strong>flashDelete</strong></td><td>:name Deleted</td></tr><tr><td><strong>flashAdd</strong></td><td>:name Added</td></tr><tr><td><strong>flashLink</strong></td><td>:name Linked</td></tr><tr><td><strong>flashRemove</strong></td><td>:name Removed</td></tr><tr><td><strong>flashUnlink</strong></td><td>:name Unlinked</td></tr></tbody></table></div></details><h3 id="вложенные-определения"><a href="#вложенные-определения" class="header-anchor">#</a> Вложенные определения</h3><p>Контроллер связей поддерживает вложение связей, другими словами, управление связями через связи. Вложенная связь использует стандартный синтаксис вложения полей. Например, определение связи <code>countries[cities]</code> делает связь <code>cities</code> доступной для управления через связь <code>countries</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">countries</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/location/models/country/fields.yaml
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/location/models/country/columns.yaml

countries<span class="token punctuation">[</span>cities<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> City
    <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/location/models/city/fields.yaml
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/location/models/city/columns.yaml
</code></pre></div><div class="custom-block tip"><p>Вложенные определения связей предназначены для бесшовной работы с <a href="./../../element/form/widget-relation.html">виджетом формы связей</a>, когда свойство <code>useController</code> установлено в <code>true</code>.</p></div><h2 id="типы-связеи"><a href="#типы-связеи" class="header-anchor">#</a> Типы связей</h2><p>Способ отображения менеджера связей зависит от определения связи в целевой модели. Тип связи также определяет требования к конфигурации, которые показаны <strong>жирным шрифтом</strong>. Доступны следующие типы связей:</p><h3 id="has-many"><a href="#has-many" class="header-anchor">#</a> Has Many</h3><ol><li>Связанные записи отображаются как список (<code>view.list</code>).</li><li>Клик по записи отобразит форму обновления (<code>manage.form</code>).</li><li>Клик по <strong>Добавить</strong> отобразит список выбора (<code>manage.list</code>).</li><li>Клик по <strong>Создать</strong> отобразит форму создания (<code>manage.form</code>).</li><li>Клик по <strong>Удалить</strong> уничтожит запись(и).</li><li>Клик по <strong>Убрать</strong> разорвёт связь.</li></ol><p>Например, если <strong>Запись блога</strong> имеет множество <strong>Комментариев</strong>, целевая модель устанавливается как запись блога и отображается список комментариев, используя столбцы из определения <code>list</code>. Клик по комментарию открывает всплывающую форму с полями, определёнными в <code>form</code>, для обновления комментария. Комментарии можно создавать таким же образом. Ниже приведён пример файла конфигурации поведения связей.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">comments</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Comment
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/blog/models/comment/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/blog/models/comment/columns.yaml
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/blog/models/comment/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>delete
</code></pre></div><h3 id="belongs-to-many"><a href="#belongs-to-many" class="header-anchor">#</a> Belongs to Many</h3><ol><li>Связанные записи отображаются как список (<code>view.list</code>).</li><li>Клик по <strong>Добавить</strong> отобразит список выбора (<code>manage.list</code>).</li><li>Клик по <strong>Создать</strong> отобразит форму создания (<code>manage.form</code>).</li><li>Клик по <strong>Удалить</strong> уничтожит запись(и) сводной таблицы.</li><li>Клик по <strong>Убрать</strong> разорвёт связь.</li></ol><p>Например, если <strong>Пользователь</strong> принадлежит многим <strong>Ролям</strong>, целевая модель устанавливается как пользователь и отображается список ролей, используя столбцы из определения <code>list</code>. Существующие роли могут быть добавлены и удалены у пользователя. Ниже приведён пример файла конфигурации поведения связей.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> add<span class="token punctuation">|</span>remove
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/role/fields.yaml
</code></pre></div><h3 id="belongs-to-many-с-данными-своднои-таблицы"><a href="#belongs-to-many-с-данными-своднои-таблицы" class="header-anchor">#</a> Belongs to Many (с данными сводной таблицы)</h3><ol><li>Связанные записи отображаются как список (<code>view.list</code>).</li><li>Клик по записи отобразит форму обновления (<code>pivot.form</code>).</li><li>Клик по <strong>Добавить</strong> отобразит список выбора (<code>manage.list</code>), затем форму ввода данных (<code>pivot.form</code>).</li><li>Клик по <strong>Убрать</strong> уничтожит запись(и) сводной таблицы.</li></ol><p>Продолжая пример со связями <strong>Belongs To Many</strong>, если роль также имеет дату истечения, клик по роли откроет всплывающую форму с полями, определёнными в <code>pivot</code>, для обновления даты истечения. Ниже приведён пример файла конфигурации поведения связей.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
    <span class="token key atrule">pivot</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/role/fields.yaml
</code></pre></div><p>Данные сводной таблицы доступны при определении полей формы и столбцов списка через связь <code>pivot</code>, см. пример ниже.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">teams</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Team
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span>
            <span class="token key atrule">columns</span><span class="token punctuation">:</span>
                <span class="token key atrule">name</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Name
                pivot<span class="token punctuation">[</span>team_color<span class="token punctuation">]</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Team color
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span>
            <span class="token key atrule">columns</span><span class="token punctuation">:</span>
                <span class="token key atrule">name</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Name
    <span class="token key atrule">pivot</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                pivot<span class="token punctuation">[</span>team_color<span class="token punctuation">]</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Team color
</code></pre></div><h3 id="belongs-to"><a href="#belongs-to" class="header-anchor">#</a> Belongs To</h3><ol><li>Связанная запись отображается как форма предпросмотра (<code>view.form</code>).</li><li>Клик по <strong>Создать</strong> отобразит форму создания (<code>manage.form</code>).</li><li>Клик по <strong>Обновить</strong> отобразит форму обновления (<code>manage.form</code>).</li><li>Клик по <strong>Связать</strong> отобразит список выбора (<code>manage.list</code>).</li><li>Клик по <strong>Отвязать</strong> разорвёт связь.</li><li>Клик по <strong>Удалить</strong> уничтожит запись.</li></ol><p>Например, если <strong>Телефон</strong> принадлежит <strong>Человеку</strong>, менеджер связей отобразит форму с полями, определёнными в <code>form</code>. Клик по кнопке Связать отобразит список людей для ассоциации с телефоном. Клик по кнопке Отвязать разорвёт связь телефона с человеком.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">person</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Person
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/person/fields.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> link<span class="token punctuation">|</span>unlink
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/person/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/person/columns.yaml
</code></pre></div><h3 id="has-one"><a href="#has-one" class="header-anchor">#</a> Has One</h3><ol><li>Связанная запись отображается как форма предпросмотра (<code>view.form</code>).</li><li>Клик по <strong>Создать</strong> отобразит форму создания (<code>manage.form</code>).</li><li>Клик по <strong>Обновить</strong> отобразит форму обновления (<code>manage.form</code>).</li><li>Клик по <strong>Связать</strong> отобразит список выбора (<code>manage.list</code>).</li><li>Клик по <strong>Отвязать</strong> разорвёт связь.</li><li>Клик по <strong>Удалить</strong> уничтожит запись.</li></ol><p>Например, если <strong>Человек</strong> имеет один <strong>Телефон</strong>, менеджер связей отобразит форму с полями, определёнными в <code>form</code>, для Телефона. При клике на кнопку Обновить появится всплывающее окно с редактируемыми полями. Если у Человека уже есть Телефон, поля обновляются, в противном случае создаётся новый Телефон.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_relation.yaml</span>
<span class="token key atrule">phone</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Phone
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/phone/fields.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> update<span class="token punctuation">|</span>delete
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/phone/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/phone/columns.yaml
</code></pre></div><h2 id="отображение-менеджера-связеи"><a href="#отображение-менеджера-связеи" class="header-anchor">#</a> Отображение менеджера связей</h2><p>Прежде чем связи могут управляться на любой странице, целевая модель должна быть инициализирована в контроллере вызовом метода <code>initRelation</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token number">7</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">initRelation</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p><a href="./form-controller.html">Контроллер форм</a> автоматически инициализирует модель при действиях создания, обновления и предпросмотра.</p></div><p>Менеджер связей затем может быть отображён для указанного определения связи вызовом метода <code>relationRender</code>. Например, если вы хотите отобразить менеджер связей на странице <a href="./form-controller.html">Предпросмотр</a>, содержимое представления <strong>preview.htm</strong> может выглядеть так.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderPreview</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Вы можете указать менеджеру связей рендериться в режиме только для чтения, передав свойство вторым аргументом.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;readOnly&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="расширение-поведения-связеи"><a href="#расширение-поведения-связеи" class="header-anchor">#</a> Расширение поведения связей</h2><p>Иногда вам может потребоваться изменить поведение связей по умолчанию, и для этого существует несколько способов.</p><h3 id="расширение-конфигурации-связеи"><a href="#расширение-конфигурации-связеи" class="header-anchor">#</a> Расширение конфигурации связей</h3><p>Предоставляет возможность манипулировать конфигурацией связей. Следующий пример может использоваться для подстановки другого файла columns.yaml на основе свойства вашей модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendConfig</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the model and field matches those you want to manipulate</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Show a different list for business customers</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">mode</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;b2b&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">view</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;$/author/plugin_name/models/mymodel/b2b_columns.yaml&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-виджета-представления"><a href="#расширение-виджета-представления" class="header-anchor">#</a> Расширение виджета представления</h3><p>Предоставляет возможность манипулировать виджетом представления. Например, вы можете переключать showCheckboxes на основе свойства вашей модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the model and field matches those you want to manipulate</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">constant</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">showCheckboxes</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="как-удалить-столбец"><a href="#как-удалить-столбец" class="header-anchor">#</a> Как удалить столбец</h4><p>Поскольку виджет ещё не завершил инициализацию в этой точке цикла выполнения, вы не можете вызвать <code>$widget-&gt;removeColumn()</code>. Метод <code>addColumns()</code>, описанный в <a href="./../lists/list-controller.html">документации контроллера списков</a>, будет работать как ожидается, но для удаления столбца нам нужно прослушивать событие &#39;list.extendColumns&#39; внутри метода <code>relationExtendViewWidget()</code>. Следующий пример показывает, как удалить столбец.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the model and field matches those you want to manipulate</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// This will work</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_column&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-виджета-управления"><a href="#расширение-виджета-управления" class="header-anchor">#</a> Расширение виджета управления</h3><p>Предоставляет возможность манипулировать виджетом управления вашей связи.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendManageWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the field is the expected one</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Manipulate widget as needed</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-виджета-своднои-таблицы"><a href="#расширение-виджета-своднои-таблицы" class="header-anchor">#</a> Расширение виджета сводной таблицы</h3><p>Предоставляет возможность манипулировать виджетом сводной таблицы вашей связи.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendPivotWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the field is the expected one</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Manipulate widget as needed</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-виджетов-фильтрации"><a href="#расширение-виджетов-фильтрации" class="header-anchor">#</a> Расширение виджетов фильтрации</h3><p>Существует два виджета фильтрации, которые могут быть расширены следующими методами: один для режима представления и один для режима управления <code>RelationController</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewFilterWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Extends the view filter widget</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendManageFilterWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Extends the manage filter widget</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Примеры программного добавления или удаления областей фильтрации можно найти в разделе <strong>Расширение областей фильтрации</strong> <a href="./../lists/list-controller.html">документации контроллера списков</a>.</p><h3 id="расширение-обновления-результатов"><a href="#расширение-обновления-результатов" class="header-anchor">#</a> Расширение обновления результатов</h3><p>Виджет представления часто обновляется, когда виджет управления вносит изменение. Вы можете использовать этот метод для внедрения дополнительных контейнеров при этом процессе. Верните массив с дополнительными значениями для отправки в браузер, например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendRefreshResults</span><span class="token punctuation">(</span><span class="token variable">$field</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the field is the expected one</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#myCounter&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Total records: 6&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../element/form/widget-relation.html">Виджет формы связей</a></li><li><a href="./../../element/content/field-entries.html">Контентное поле записей</a></li></ul></div>`,87))])}const v=o(i,[["render",d]]);export{f as __pageData,v as default};
